CAT = "ukdscLaw"; SEG = "LAW"
# England and Wales questions follow the Deer Act 1991 (Schedule 1 as substituted 2007); Scottish ones say Scotland.
Q = [
("In England and Wales, what is the close season for roe bucks?",
 "1 November to 31 March", ["1 April to 31 October", "1 May to 31 July", "1 January to 30 September"],
 "Schedule 1 of the Deer Act 1991 protects roe bucks from 1 November to 31 March, when they have cast or are growing antlers. Roe does are protected from 1 April to 31 October."),
("In England and Wales, what is the close season for roe does?",
 "1 April to 31 October", ["1 November to 31 March", "1 May to 31 July", "16 February to 20 October"],
 "Roe does are protected from 1 April to 31 October under Schedule 1 of the Deer Act 1991. The 16 February to 20 October season is the Scottish one for red, sika and fallow females."),
("In England and Wales, what is the close season for red stags?",
 "1 May to 31 July", ["1 November to 31 March", "1 April to 31 October", "21 October to 30 June"],
 "Red stags are protected from 1 May to 31 July. The 21 October to 30 June season was the old Scottish one and no longer applies since 2023."),
("In England and Wales, red hinds may not be shot between:",
 "1 April and 31 October", ["1 May and 31 July", "1 November and 31 March", "16 February and 20 October"],
 "Hinds, like all female deer protected by Schedule 1, have a close season of 1 April to 31 October. This protects them while they carry and rear young."),
("In England and Wales, what is the close season for fallow bucks?",
 "From 1 May until 31 July", ["From 1 April until 31 October", "From 1 November until 31 March", "From 1 August until 31 October"],
 "Fallow bucks are protected from 1 May to 31 July under Schedule 1, the same dates as red and sika stags."),
("In England and Wales, a fallow doe is in her close season from:",
 "From 1 April until 31 October", ["From 1 May until 31 July", "From 1 November until 31 March", "From 1 December until 28 February"],
 "Fallow does are protected from 1 April to 31 October. A doe shot in that period is an offence unless an exception such as preventing suffering applies."),
("In England and Wales, sika hinds are protected from:",
 "1 April through 31 October", ["1 May through 31 July", "1 November through 31 March", "16 February through 20 October"],
 "Sika stags are protected from 1 May to 31 July and hinds from 1 April to 31 October."),
("In England and Wales, a red/sika hybrid stag has which close season?",
 "1 May through 31 July", ["1 April through 31 October", "No close season at all", "1 November through 31 March"],
 "Schedule 1 gives red/sika hybrids the same close seasons as the parent species: stags 1 May to 31 July and hinds 1 April to 31 October."),
("In England and Wales, what is the close season for Chinese water deer?",
 "1 April to 31 October, both sexes", ["1 May to 31 July, bucks only", "1 November to 31 March, both sexes", "No close season for either sex"],
 "Schedule 1 protects both bucks and does from 1 April to 31 October. The sexes are hard to tell apart in the field."),
("What does section 2 of the Deer Act 1991 make an offence in a deer's close season?",
 "Taking or intentionally killing it", ["Only wounding it without killing", "Only selling its venison afterwards", "Only shooting it at night time"],
 "Section 2 covers taking or intentionally killing a deer of a species and description listed in Schedule 1 during its prescribed close season, unless a statutory exception applies."),
("Which wild deer species has no close season in England and Wales?",
 "Muntjac", ["Roe deer", "Chinese water deer", "Fallow deer"],
 "Muntjac are not listed in Schedule 1 of the Deer Act 1991 because they breed all year round. The other species all have a close season for at least one sex."),
("Under section 3 of the Deer Act 1991, taking or killing deer is an offence during which period?",
 "One hour after sunset to one hour before sunrise", ["Half an hour after sunset to half an hour before sunrise", "From sunset until sunrise", "Between 10 pm and 5 am"],
 "Section 3 makes it an offence to take or kill deer from the expiry of the first hour after sunset to the beginning of the last hour before sunrise, unless an exception applies."),
("How does the night period in section 18 of the Deer (Scotland) Act 1996 compare with the English one?",
 "It is defined the same way", ["It starts at sunset and ends at sunrise", "It is shorter by two hours", "It applies only in winter"],
 "Section 18 uses the same wording: from the expiration of the first hour after sunset to the commencement of the last hour before sunrise. An occupier can be authorised by NatureScot to take deer at night where necessary to prevent damage or protect public safety."),
("In England and Wales, a smooth-bore gun may be used on deer under which provision?",
 "Section 7, to prevent crop damage", ["Section 2, in the close season", "Section 1, with the owner's consent", "Section 3, to shoot at night"],
 "Schedule 2 lists any smooth-bore gun as prohibited, but section 7 allows a 12 bore shotgun on cultivated land, pasture or enclosed woodland where deer are causing serious damage. Sections 1, 2 and 3 are prohibitions, not permissions."),
("Is an air rifle a lawful way to kill a deer under the Deer Act 1991?",
 "No, air weapons are prohibited", ["Yes, if it exceeds 12 foot-pounds", "Yes, when fired from a high seat", "Yes, for roe deer in the open season"],
 "Schedule 2 prohibits any air gun, air rifle or air pistol for taking deer. A limited exception for an injured deer relies on section 6(4), which allows any reasonable means to kill one too injured to survive."),
("Under section 4 of the Deer Act 1991, which act involving a vehicle is an offence?",
 "Shooting from a moving vehicle", ["Driving to the stalking ground at dawn", "Watching deer from a parked vehicle", "Carrying a rifle in a case in the boot"],
 "Section 4 prohibits firing a firearm or projecting a missile at deer from a moving vehicle or one with its engine running, and using a vehicle to drive deer. Watching from a parked vehicle is lawful."),
("Under section 4, using a motor vehicle to drive deer towards a rifle is:",
 "An offence", ["Allowed on private land", "Allowed in the close season only", "Allowed with a high seat"],
 "Section 4(4) prohibits using a motor vehicle to drive deer. Occupiers of enclosed land where deer are usually kept have a limited exception for deer on that land."),
("Which of these methods of taking deer does section 4 of the Deer Act 1991 prohibit?",
 "Snares and poisoned or stupefying bait", ["Zeroed rifle with soft-nosed ammunition", "Calling a deer in with a whistle", "High seat with a legal rifle"],
 "Section 4 prohibits setting or using traps, snares, poisoned or stupefying bait and nets, and the use of arrows, spears and similar missiles."),
("Under section 1 of the Deer Act 1991, which of these is an offence if done without the consent of the owner or occupier?",
 "Entering land to look for deer to take", ["Walking a public footpath across the land", "Photographing deer from a public lane", "Counting deer from the roadside verge"],
 "Section 1 makes it an offence to enter land without consent or lawful authority in order to search for or pursue deer with the intention of taking, killing or injuring them. Having no intention to take a deer is not covered."),
("Without consent or lawful authority, which of these is an offence under section 1 of the Deer Act 1991?",
 "Removing a deer carcase from land", ["Photographing a deer on the land", "Feeding deer in your own garden", "Counting deer from a high-level hide"],
 "Section 1(2) includes removing a deer carcase from land without consent or lawful authority, as well as taking, killing or injuring a deer."),
("Who is an \"authorised person\" for the poaching offences in section 1 of the Deer Act 1991?",
 "Owner, occupier or anyone they appoint", ["Only a uniformed police officer on duty", "Any registered deer manager in the county", "Only a gamekeeper employed on the estate"],
 "An authorised person can require a suspected poacher to give their full name and address and to leave the land immediately. Refusing is itself an offence."),
("In what circumstance is a person not guilty of a section 1 offence?",
 "They believed the owner would agree", ["They held a valid firearm certificate", "They had never taken a deer before", "They were within sight of a public road"],
 "Section 1(3) gives a defence where the person believed the owner or occupier would have consented had they known the circumstances, or believed they had other lawful authority."),
("Which condition must be met before the section 7 crop-damage defence applies?",
 "It was necessary to stop serious damage", ["The deer had been seen there twice before", "The occupier must live on the farm itself", "The damage must be to a public footpath"],
 "Section 7 requires reasonable grounds to believe deer of that species were causing damage to crops, vegetables, fruit, growing timber or other property, that further serious damage was likely, and that the action was necessary to prevent it."),
("Under section 7 of the Deer Act 1991, a shotgun may be used on deer only if it is at least:",
 "12 bore with AAA shot or a 22.68 g slug", ["12 bore with number 6 shot or a 10 g slug", "16 bore with BB shot or a 22.68 g slug", "20 bore with any shot or a 30 g slug"],
 "The section 7 exception allows a smooth-bore gun of at least 12 bore loaded with a single non-spherical projectile weighing at least 22.68 grammes (350 grains) or AAA shot. Smaller bores and smaller shot do not qualify."),
("Who may use the section 7 defence in the close season on cultivated land, pasture or enclosed woodland?",
 "Occupiers, or others authorised in writing", ["Anyone who finds deer damaging the land nearby", "Any holder of a valid firearm certificate", "A neighbouring landowner or their stalker"],
 "The occupier may act in person. A member of the household or an employee needs the occupier's written authority, as does a person with the right to take deer or someone acting under that right-holder's written authority."),
("For how long can Natural England or Natural Resources Wales licence close season or night shooting?",
 "Up to two years", ["Up to three months", "Up to five years", "For the licence holder's lifetime"],
 "Section 8 licences can allow close season or night taking for public safety, natural heritage conservation or preventing serious property damage. Each licence must state its purpose, land, species and method and can run for up to two years."),
("In England and Wales, which action does the Deer Act 1991 allow in the close season?",
 "Killing a deer to prevent its suffering", ["Shooting a doe for venison for the freezer", "Stalking a buck for a trophy head", "Culling by lamp for sport at night"],
 "Section 6 gives an exception for acts done to prevent the suffering of an injured or diseased deer. It allows any reasonable means, meaning a method reasonably expected to cause rapid unconsciousness and death."),
("Taking or killing a deer in the close season is not an offence under section 2 if the person:",
 "Reasonably believes its mother is lost", ["Believes it might wander onto a busy road", "Wants the venison for their own freezer", "Holds a current firearm certificate"],
 "An exception added in 2007 covers a deer the person reasonably believes has lost, or is about to lose, the female it depended on. The exception does not cover a person who took the deer unlawfully."),
("Deer kept by way of business for meat on land with a deer-proof barrier, and conspicuously marked, are:",
 "Not covered by the close season offence", ["Protected by the close season as normal", "Covered by the close season in Wales only", "Protected by the close season in July"],
 "Section 2(3) excludes killing deer kept by way of business on enclosed land, if they are conspicuously marked to identify them as that person's and are kept for meat, other foodstuffs, skins, by-products or breeding stock."),
("On which days of the week may deer lawfully be stalked outside the close season?",
 "Any day, including public holidays", ["Never on Sundays, whatever the season", "Never on public holidays", "Weekdays only, outside public holidays"],
 "The Deer Initiative's close seasons guide says deer can be shot on any day of the week including all public holidays, provided the species, sex and time of year are lawful."),
("To use a rifle for deer stalking in Great Britain, you need:",
 "A firearm certificate", ["A shotgun certificate", "Written permission from the landowner alone", "No certificate if used on private land"],
 "Under section 1 of the Firearms Act 1968 a rifle needs a firearm certificate, whereas a shotgun covered by the Act's definition needs only a shotgun certificate. Landowner permission is a separate matter."),
("The Deer Act 1991 allows rifles smaller than the usual minimum only for which two species?",
 "Chinese water deer and muntjac", ["Roe deer and fallow deer in woodland", "Sika deer and red deer on open hill", "Muntjac and roe deer in woodland"],
 "Section 6 lets a rifle of at least .220 inch and 1,356 joules (1,000 foot-pounds) with a soft-nosed or hollow-nosed bullet of at least 50 grains be used only on Chinese water deer and muntjac."),
("In Scotland, when does the close season for female red, sika and fallow deer run?",
 "16 February to 20 October", ["1 April to 31 October", "21 October to 30 June", "16 February to 31 October"],
 "The Deer (Close Seasons) (Scotland) Order 2011 sets this season for female red, sika, fallow and red/sika hybrid deer, and the 2023 amendment left it unchanged."),
("In Scotland, what is the close season for female roe deer?",
 "1 April to 20 October", ["16 February to 20 October", "1 November to 31 March", "1 April to 31 October"],
 "Scottish roe does are protected from 1 April to 20 October. The season ends on 20 October, not 31 October as in England and Wales."),
("Since 21 October 2023, which statement is true of male deer in Scotland?",
 "They have no close season", ["Stags are protected until 30 June", "Roe bucks are protected until 31 March", "Fallow bucks are protected in May"],
 "The Deer (Close Seasons) (Scotland) Amendment Order 2023 removed the close seasons for male deer of all species. The female close seasons remain."),
("From 3 November 2023, what is the minimum bullet weight in the Scottish firearms order?",
 "80 grains (5.3 grams)", ["50 grains (3.24 grams)", "100 grains (6.48 grams)", "120 grains (7.8 grams)"],
 "The Deer (Firearms etc.) (Scotland) Amendment Order 2023 cut the minimum from 100 to 80 grains, which allows non-lead ammunition. It also lets night shooting use light-intensifying and heat-sensitive sights."),
("In Scotland, who may authorise an occupier to take deer at night to prevent damage?",
 "NatureScot", ["The local council", "The Scottish Land Commission", "The occupier's neighbour"],
 "Section 18 of the Deer (Scotland) Act 1996 lets the nature agency authorise an occupier or their nominee if the taking is necessary to prevent damage or in the interests of public safety and no other reasonable means would do."),
("In Scotland, who can authorise close season culling to prevent crop damage or protect natural heritage?",
 "NatureScot", ["The Firearms Licensing Department", "The local police", "The Forestry Commission"],
 "Section 5 of the Deer (Scotland) Act 1996 lets NatureScot authorise taking or killing deer in the close season for damage prevention, public safety or scientific purposes where no other reasonable control would be adequate."),
("In Scotland, section 21 of the Deer (Scotland) Act 1996 gives power to make orders on:",
 "Firearms, ammunition and sights", ["Which estates may let stalking", "The size of each cull", "Who wears high-visibility clothing"],
 "Section 21 allows orders on the classes of firearms, ammunition, sights and other equipment that may lawfully be used on deer. Breaching such an order is an offence."),
("On 1 August in England and Wales, which statement about a fallow buck and a roe buck is correct?",
 "Both are in season", ["Neither is in season", "Only the fallow buck is in season", "Only the roe buck is in season"],
 "A fallow buck's close season ends on 31 July. A roe buck's close season runs 1 November to 31 March, so both can be shot on 1 August if every other condition is met."),
]
